{"content":"import { Task, ScheduleDay, ScheduleResult } from "./types";

export function schedule(tasks: Task[], capacity: number): ScheduleResult {
  const todoTasks = tasks.filter((t) => t.status === "todo");

  // Sort: highest priority first, then by insertion order (createdAt ascending)
  const sorted = [...todoTasks].sort((a, b) => {
    if (b.priority !== a.priority) return b.priority - a.priority;
    return a.createdAt.localeCompare(b.createdAt);
  });

  const days: ScheduleDay[] = [];
  const unschedulable: Task[] = [];

  for (const task of sorted) {
    if (task.estimate > capacity) {
      unschedulable.push(task);
      continue;
    }

    // Find the first day that can fit this task
    let placed = false;
    for (const day of days) {
      if (day.totalPoints + task.estimate <= capacity) {
        day.tasks.push(task);
        day.totalPoints += task.estimate;
        placed = true;
        break;
      }
    }

    if (!placed) {
      const newDay: ScheduleDay = {
        day: days.length + 1,
        tasks: [task],
        totalPoints: task.estimate,
      };
      days.push(newDay);
    }
  }

  return { days, unschedulable };
}
