{"content":"import express from "express";
import path from "path";
import { store } from "./store";
import { schedule } from "./schedule";

export function createApp(): express.Express {
  const app = express();

  app.use(express.json());
  app.use(express.static("public"));

  // POST /api/tasks — create a task
  app.post("/api/tasks", (req, res) => {
    const { title, priority, estimate } = req.body;

    if (!title || typeof title !== "string" || title.trim() === "") {
      return res.status(400).json({ error: "title is required and must be a non-empty string" });
    }

    if (!Number.isInteger(priority) || priority < 1 || priority > 5) {
      return res.status(400).json({ error: "priority must be an integer between 1 and 5" });
    }

    if (typeof estimate !== "number" || !Number.isFinite(estimate) || estimate <= 0) {
      return res.status(400).json({ error: "estimate must be a positive number" });
    }

    const task = store.create({ title, priority, estimate });
    return res.status(201).json(task);
  });

  // GET /api/tasks — list all tasks
  app.get("/api/tasks", (_req, res) => {
    return res.status(200).json(store.getAll());
  });

  // PATCH /api/tasks/:id — update task status
  app.patch("/api/tasks/:id", (req, res) => {
    const { status } = req.body;

    if (!status || !["todo", "doing", "done"].includes(status)) {
      return res.status(400).json({ error: "status must be one of: todo, doing, done" });
    }

    const id = parseInt(req.params.id, 10);
    if (isNaN(id)) {
      return res.status(404).json({ error: "task not found" });
    }

    const task = store.updateStatus(id, status as "todo" | "doing" | "done");
    if (!task) {
      return res.status(404).json({ error: "task not found" });
    }

    return res.status(200).json(task);
  });

  // DELETE /api/tasks/:id — delete a task
  app.delete("/api/tasks/:id", (req, res) => {
    const id = parseInt(req.params.id, 10);
    if (isNaN(id)) {
      return res.status(404).json({ error: "task not found" });
    }

    const deleted = store.delete(id);
    if (!deleted) {
      return res.status(404).json({ error: "task not found" });
    }

    return res.status(204).send();
  });

  // GET /api/schedule?capacity=N — run the schedule engine
  app.get("/api/schedule", (req, res) => {
    const capacityStr = req.query.capacity;

    if (!capacityStr || typeof capacityStr !== "string") {
      return res.status(400).json({ error: "capacity query parameter is required" });
    }

    const capacity = Number(capacityStr);
    if (isNaN(capacity) || !Number.isFinite(capacity) || capacity < 1) {
      return res.status(400).json({ error: "capacity must be a positive number" });
    }

    const tasks = store.getAll();
    const result = schedule(tasks, capacity);
    return res.status(200).json(result);
  });

  // Catch-all: serve SPA index.html for any unmatched route
  app.use((_req, res) => {
    res.sendFile(path.resolve("public", "index.html"));
  });

  // Global error handler — catches DB errors, etc.
  app.use((err: Error, _req: express.Request, res: express.Response, _next: express.NextFunction) => {
    console.error("Server error:", err.message);
    return res.status(500).json({ error: "internal server error" });
  });

  return app;
}

const port = process.env.PORT || "3000";
createApp().listen(port, () => {
  console.log(`Server listening on port ${port}`);
});
